def zone(uri):
    name = uri.split('#')[-1]
    return name.split('.')[0]

# Group by zone
zones = {}
for r in rows:
    z = zone(r['point_uri'])
    zones.setdefault(z, set()).add((r['point_class'], r['timeseries_id']))

for z in sorted(zones):
    if z.startswith('Zone_F3') or 'F3' in z:
        print(z, sorted(zones[z]))

