import csv
from collections import defaultdict

def load(ts):
    d=defaultdict(dict)
    ids={ts}
    with open(VALUES_CSV, newline='', encoding='utf-8') as f:
        for r in csv.DictReader(f):
            if r['timeseries_id'] in ids:
                d[ts][r['timestamp']]=float(r['value'])
    return d

def ma(data, y, m):
    v=[x for ts,x in data.items() if ts.startswith(f"{y}-{m:02d}")]
    return sum(v)/len(v)

Z01=load('e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8')['e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8']
Z02=load('bcc5a78f-36a4-55a0-9420-7a80fc9b2deb')['bcc5a78f-36a4-55a0-9420-7a80fc9b2deb']
Z05=load('c49bbc2f-096e-5e16-bead-066250790308')['c49bbc2f-096e-5e16-bead-066250790308']

print("Month:  F3Z01  F3Z02  F3Z05   Z01-Z02   Z01-Z05")
for m in range(1,13):
    a=ma(Z01,2018,m); b=ma(Z02,2018,m); c=ma(Z05,2018,m)
    print(f"{m:2d}      {a:5.2f} {b:5.2f} {c:5.2f}   {a-b:+5.2f}   {a-c:+5.2f}")

# December / winter gap — a sensor bias rarely exceeds ~1-2C
print("\nWinter (Dec) gaps:  Z01-Z02 = %.2f C,  Z01-Z05 = %.2f C"%(ma(Z01,2018,12)-ma(Z02,2018,12), ma(Z01,2018,12)-ma(Z05,2018,12)))
print("This gap is persistent & widens through the year -> real zone shift, not a small calibration bias.")
